CREATE PROCEDURE usp_OptimizeAllTables
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @TableName NVARCHAR(128);
    DECLARE @SQL NVARCHAR(MAX);

    -- Create a temporary table to store the names of all tables in the database
    CREATE TABLE #TempTables (TableName NVARCHAR(128));

    -- Insert all table names into the temporary table
    INSERT INTO #TempTables (TableName)
    SELECT name FROM sys.tables;

    -- Declare a cursor to iterate over each table
    DECLARE TableCursor CURSOR FOR
        SELECT TableName FROM #TempTables;

    OPEN TableCursor;

    FETCH NEXT FROM TableCursor INTO @TableName;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        -- Construct dynamic SQL to rebuild indexes for the current table
        SET @SQL = 'ALTER INDEX ALL ON [' + @TableName + '] REBUILD WITH (ONLINE = ON)';

        -- Execute the dynamic SQL
        EXEC sp_executesql @SQL;

        FETCH NEXT FROM TableCursor INTO @TableName;
    END

    CLOSE TableCursor;
    DEALLOCATE TableCursor;

    -- Drop the temporary table
    DROP TABLE #TempTables;
END;
